55	const PROCESSING_FEE = 5;
56	
57	const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
58	  sword: 100,
59	  amulet: 60,
60	  staff: 80,
61	};
62	
63	export function runScenario(scenario: Scenario): ScenarioResult {
64	  const quoteStep = scenario.steps[0] as QuoteStep;
65	  const basePremium = quoteStep.items.reduce(
66	    (sum, item) => sum + BASE_PREMIUM_BY_ITEM_TYPE[item.type],
67	    0,
68	  );
69	  return { results: [{ premium: basePremium + PROCESSING_FEE }] };
70	}
